BEGIN;
CREATE TABLE IF NOT EXISTS inventory_cycles (id uuid PRIMARY KEY, name varchar(200) NOT NULL, created_at timestamptz NOT NULL, source_file varchar(500) NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_batches (id uuid PRIMARY KEY, cycle_id uuid NOT NULL REFERENCES inventory_cycles(id) ON DELETE CASCADE, sku varchar(100) NOT NULL, name varchar(300) NOT NULL, quantity numeric(14,3) NOT NULL CHECK (quantity >= 0), warning_threshold numeric(14,3), batch_no varchar(120) NOT NULL, expiry_date date, source_row integer, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(cycle_id, sku, batch_no));
CREATE TABLE IF NOT EXISTS outbound_records (id uuid PRIMARY KEY, cycle_id uuid NOT NULL REFERENCES inventory_cycles(id) ON DELETE CASCADE, document_no varchar(120) NOT NULL DEFAULT '', record_date date, department varchar(200) NOT NULL DEFAULT '', product_code varchar(100) NOT NULL DEFAULT '', name varchar(300) NOT NULL, quantity numeric(14,3) NOT NULL CHECK (quantity > 0), batch_no varchar(120) NOT NULL DEFAULT '', expiry_date date, matched_batch_id uuid REFERENCES inventory_batches(id) ON DELETE SET NULL, match_status varchar(20) NOT NULL CHECK (match_status IN ('matched','unmatched','overdrawn')), source_key varchar(500) NOT NULL, created_at timestamptz NOT NULL, UNIQUE(cycle_id, source_key));
CREATE TABLE IF NOT EXISTS app_settings (id smallint PRIMARY KEY CHECK (id = 1), current_cycle_id uuid REFERENCES inventory_cycles(id) ON DELETE SET NULL, low_stock_threshold numeric(14,3) NOT NULL DEFAULT 20, expiry_warning_days integer NOT NULL DEFAULT 90, revision bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS recognition_drafts (id uuid PRIMARY KEY, actor varchar(120) NOT NULL, document_type varchar(20) NOT NULL CHECK (document_type IN ('inbound','outbound')), result jsonb NOT NULL, status varchar(20) NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_credentials (username varchar(120) PRIMARY KEY, password_hash text NOT NULL, must_change_password boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor varchar(120) NOT NULL, action varchar(100) NOT NULL, entity_type varchar(100) NOT NULL, after_value jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS inventory_batches_cycle_idx ON inventory_batches(cycle_id);
CREATE INDEX IF NOT EXISTS outbound_records_cycle_idx ON outbound_records(cycle_id);
CREATE INDEX IF NOT EXISTS recognition_drafts_created_idx ON recognition_drafts(created_at DESC);
COMMIT;
